/**
 * Process-wide record of completed probe resource cleanups.
 *
 * The store deliberately lives outside the Nest container so that cleanup
 * results accumulated by one application instance remain readable after the
 * application is closed and a new one is created from the same module.
 */
export interface ProbeCleanupCounts {
  request: number;
  transient: number;
  singleton: number;
}

const completedCleanups: ProbeCleanupCounts = {
  request: 0,
  transient: 0,
  singleton: 0,
};

let requestSeq = 0;
let transientSeq = 0;
let singletonSeq = 0;

export const ProbeCleanupStore = {
  nextRequestId: () => `request-${++requestSeq}`,
  nextTransientId: () => `transient-${++transientSeq}`,
  nextSingletonId: () => `singleton-${++singletonSeq}`,
  recordCleanup(kind: keyof ProbeCleanupCounts): void {
    completedCleanups[kind]++;
  },
  snapshot(): ProbeCleanupCounts {
    return { ...completedCleanups };
  },
};
```

